def make(base_r,base_c=13):
    g=[[3]*27 for _ in range(27)]
    for i,row in enumerate(key):
        for j,v in enumerate(row):
            if v:
                g[1+2*i][1+2*j]=v
                for r in range(base_r+5*i,base_r+5*i+4):
                    for c in range(base_c+5*j,base_c+5*j+4):g[r][c]=v
    return g
